window.COURSES = window.COURSES || []; window.TIPS = window.TIPS || [];
window.COURSES.push(
{ id:"mi01", cat:"mind", e:"🧱", title:"Atomic Habits Essentials", sub:"Tiny changes, compounding results", cards:[
 {e:"📈", h:"Small gains compound", t:"James Clear argues that tiny daily improvements stack like interest. A habit that feels trivial today shapes who you are in a year, because the direction you move matters more than the size of one step.", stat:{n:"37x", l:"growth from getting 1% better daily for a year (1.01^365)"}},
 {e:"🪪", h:"Identity beats outcomes", t:"Most people set outcome goals like 'run a marathon'. Clear suggests choosing an identity instead: 'I am a runner'. Each small action becomes a vote for that identity, and behavior follows who you believe you are."},
 {e:"🔁", h:"The four-step loop", t:"Every habit runs on cue, craving, response, reward. To build a habit, work on all four. To break one, invert them. Understanding the loop turns vague willpower problems into specific design problems.", list:["Cue: make it obvious","Craving: make it attractive","Response: make it easy","Reward: make it satisfying"]},
 {e:"📍", h:"Name when and where", t:"Vague intentions fail. An implementation intention states the exact time and place: 'After I pour my coffee, I will write for ten minutes at the kitchen table.' Specifics remove the daily decision about whether to start."},
 {e:"🔗", h:"Stack habits together", t:"Habit stacking attaches a new behavior to one you already do reliably. 'After I brush my teeth, I will floss one tooth.' The existing habit acts as an automatic cue, so you rely less on memory or motivation."},
 {e:"⏱️", h:"The two-minute rule", t:"Scale any habit down until it takes two minutes or less. 'Read before bed' becomes 'read one page.' The goal is to master showing up first, because a habit must be established before it can be improved.", stat:{n:"2 min", l:"suggested starting size for a new habit"}},
 {e:"🏠", h:"Design your environment", t:"Environment often beats willpower. Put the guitar on a stand in the living room, leave fruit on the counter, and hide your phone charger in another room. Make good cues visible and bad cues invisible."},
 {e:"🕰️", h:"Never miss twice", t:"Everyone slips. The danger is the second miss, which turns a lapse into a new pattern. Clear's rule is simple: if you skip a day, make getting back on track the very next day your only priority.", stat:{n:"66 days", l:"median time to automaticity in a 2009 UCL study (range 18 to 254)"}}
], quiz:[
 {q:"What does the habit loop consist of?", o:["Cue, craving, response, reward","Goal, plan, effort, result","Trigger, stress, action, relief"], a:0, w:"Clear's model has four stages: cue, craving, response and reward."},
 {q:"What is an implementation intention?", o:["A big yearly goal","A plan naming the exact time and place","A vague wish to improve"], a:1, w:"It links a specific behavior to a specific time and location, removing the decision to start."},
 {q:"According to the book, what should drive habit change first?", o:["Maximum willpower","Outcome targets","Identity you want to become"], a:2, w:"Identity-based habits mean each action reinforces who you believe you are."},
 {q:"What does the 'never miss twice' rule protect against?", o:["A single lapse turning into a new pattern","Buying the wrong gear","Doing too few habits"], a:0, w:"One miss is an accident, two misses start a new habit of not doing it."}
]},
{ id:"mi02", cat:"mind", e:"🎧", title:"Deep Work and Focus", sub:"Cal Newport on valuable concentration", cards:[
 {e:"🔬", h:"What deep work means", t:"Cal Newport defines deep work as professional activity done in a state of distraction-free concentration that pushes your cognitive abilities to their limit. It produces new value and is hard to replicate, unlike shallow tasks such as email."},
 {e:"💰", h:"Why it is valuable", t:"Newport argues that the ability to learn hard things quickly and produce at a high level is increasingly rare and rewarded. The skill compounds, so people who train focus gain a lasting edge over those who stay constantly reactive."},
 {e:"🔄", h:"Attention residue", t:"Researcher Sophie Leroy found that switching tasks leaves part of your attention stuck on the previous one. Checking messages 'just quickly' mid-task lowers the quality of what follows. Protect blocks from interruptions entirely.", stat:{n:"23 min", l:"often-cited time to fully refocus after an interruption (Gloria Mark's research)"}},
 {e:"🗓️", h:"Four scheduling styles", t:"Newport describes different ways to fit depth into life. Pick the one your job allows and stick to it, because a plan you can sustain beats an ideal one you abandon.", list:["Monastic: remove shallow work","Bimodal: whole days or weeks","Rhythmic: same daily block","Journalistic: slot in when free"]},
 {e:"🚪", h:"Ritualize your sessions", t:"Decide where you will work, for how long, and what rules apply. Include logistics like coffee and water so you never need to leave. A consistent ritual signals the brain that it is time to concentrate."},
 {e:"⚖️", h:"Limits are normal", t:"Newport notes that even elite performers rarely sustain more than about four hours of deep work a day. Beginners may manage one hour. Build up gradually and treat the limit as a feature, not a failure.", stat:{n:"~4 hours", l:"typical daily ceiling for deliberate concentration"}},
 {e:"🌙", h:"Embrace real downtime", t:"Newport proposes a shutdown ritual at day's end: review tasks, plan tomorrow, and say a closing phrase. Resting fully lets your mind recover, and he argues evening work rarely adds enough to justify the cost."},
 {e:"📵", h:"Train against distraction", t:"Boredom tolerance is a skill. Instead of reaching for your phone in every queue, let your mind idle. Schedule your internet use in advance rather than scheduling breaks from it, so craving novelty loses power."}
], quiz:[
 {q:"What is attention residue?", o:["Fatigue after a long day","Part of your attention staying on the previous task","Forgetting what you read"], a:1, w:"Task switching leaves your mind partly occupied by the earlier task, hurting performance."},
 {q:"Which is a recommended way to schedule deep work?", o:["Only when inspired","Only on weekends","A rhythmic daily block at the same time"], a:2, w:"Newport lists rhythmic scheduling as a reliable approach for many people."},
 {q:"What is a shutdown ritual meant to do?", o:["Let you fully disengage from work","Add extra tasks to the evening","Replace sleep"], a:0, w:"It closes open loops so your mind can rest and recover."},
 {q:"How much deep work can most people sustain daily?", o:["10 hours","Around 4 hours at most","Exactly 8 hours"], a:1, w:"Even experts rarely exceed roughly four hours of intense concentration."}
]},
{ id:"mi03", cat:"mind", e:"🌱", title:"Mindset: Fixed vs Growth", sub:"Carol Dweck's research in plain words", cards:[
 {e:"🧠", h:"Two ways of thinking", t:"Psychologist Carol Dweck describes a fixed mindset, believing talent is set, and a growth mindset, believing abilities develop through effort and strategy. Most people hold a mix that shifts by domain and situation."},
 {e:"🛑", h:"Challenges feel different", t:"Under a fixed mindset, difficulty feels like proof you are not smart enough, so you avoid it. Under a growth mindset, difficulty signals that you are stretching. The same setback becomes either a verdict or information."},
 {e:"👏", h:"Praise effort, not talent", t:"In Dweck's classic experiments, children praised for intelligence picked easier tasks afterward, while children praised for effort and strategy chose harder ones. Process praise keeps people willing to risk failure.", stat:{n:"~400", l:"fifth graders in Dweck and Mueller's 1998 praise studies"}},
 {e:"⚠️", h:"Beware false growth", t:"A false growth mindset is praising effort even when it does not work. Dweck stresses that effort must come with learning: trying new strategies and asking for help. Working hard with a failing method is not growth."},
 {e:"🗣️", h:"Spot your fixed voice", t:"Notice the internal commentary that says 'I'm just bad at this' or 'they're naturally gifted.' Name it, then answer it with a growth reply. Awareness is the first step to changing a habitual interpretation.", list:["Hear the fixed voice","Recognize it has a choice","Talk back with growth","Take the growth action"]},
 {e:"➕", h:"Add the word yet", t:"Replace 'I can't do this' with 'I can't do this yet.' The single word reframes a current limit as a stage on a path. It is small, but it changes what you do next: practice instead of retreat."},
 {e:"📚", h:"Mistakes as data", t:"Brain imaging work suggests people with growth beliefs pay closer attention to errors and corrections. In practice, after a failure ask what it reveals and which strategy to try next, rather than what it says about you."},
 {e:"🔭", h:"Evidence is mixed", t:"Large replications show the effect of mindset interventions is real but modest, bigger for struggling students. Treat the idea as a useful lens, not magic. Pair belief with good strategies, feedback and support."}
], quiz:[
 {q:"What does a growth mindset assume?", o:["Talent is fixed at birth","Failure should be avoided","Abilities can develop through effort and strategy"], a:2, w:"Dweck defines it as believing abilities are developable."},
 {q:"In Dweck's studies, which praise led to harder task choices?", o:["Praise for effort and strategy","Praise for being smart","No praise"], a:0, w:"Process praise encouraged children to take on challenges."},
 {q:"What is a 'false growth mindset'?", o:["Believing in change","Praising effort even when no learning occurs","Setting goals"], a:1, w:"Effort alone is not enough without learning and better strategies."},
 {q:"How strong are mindset interventions according to large replications?", o:["Zero","Huge for everybody","Modest but real, especially for strugglers"], a:2, w:"Effects are small on average but larger for struggling students."}
]},
{ id:"mi04", cat:"mind", e:"🔥", title:"Discipline and Resilience", sub:"Lessons from Can't Hurt Me and beyond", cards:[
 {e:"🏔️", h:"Origin of the story", t:"David Goggins grew up amid abuse and poverty, then became a Navy SEAL, ultra-endurance runner and pull-up record holder. His book Can't Hurt Me argues you can rebuild yourself through deliberately chosen hardship."},
 {e:"🪞", h:"The accountability mirror", t:"Goggins tells readers to write their goals and honest flaws on sticky notes and stick them on a mirror, then face them daily. It is a blunt way to stop lying to yourself about what you are avoiding."},
 {e:"🧮", h:"The 40 percent rule", t:"Goggins claims that when your mind says you are done, you have only used about 40 percent of your capacity. This is a motivational heuristic, not a measured fact, but it does match research showing perceived limits arrive before physical ones.", stat:{n:"40%", l:"Goggins' motivational rule of thumb, not a scientific figure"}},
 {e:"📋", h:"Cookie jar of wins", t:"Mentally collect past victories you earned through struggle. When hard moments arrive, open that 'jar' and remember you have survived before. Recalling concrete evidence is more convincing than empty positive self-talk."},
 {e:"🛡️", h:"What resilience really is", t:"Psychologists treat resilience as adapting well to adversity, not being unbothered. It is common, learnable, and built through supportive relationships, realistic optimism, and treating setbacks as problems to solve."},
 {e:"🧊", h:"Do the uncomfortable thing", t:"Voluntary discomfort builds tolerance. Start small and safe: a cold finish to your shower, a hard workout on a low-energy day, or an awkward call you have been avoiding. Gradual exposure beats heroic one-offs.", list:["Pick one small discomfort","Do it at a set time","Finish before judging","Repeat tomorrow"]},
 {e:"🧭", h:"Discipline versus motivation", t:"Motivation is a feeling that comes and goes. Discipline is following a decision after the mood has left. Reduce the reliance on mood with schedules, defaults, and commitments made in advance."},
 {e:"⚠️", h:"A critical caution", t:"Extreme grind culture can ignore injury, burnout and mental health. Take the useful parts, like honest self-assessment and persistence, but build recovery and professional support into your plan. Toughness includes knowing when to rest."}
], quiz:[
 {q:"What is the accountability mirror?", o:["Writing goals and flaws where you see them daily","A fitness tracker","A gym mirror trick"], a:0, w:"You post honest notes on the mirror to confront avoidance every day."},
 {q:"How should the 40 percent rule be understood?", o:["A proven physiological law","A motivational heuristic","A fixed training formula"], a:1, w:"It is a rule of thumb meant to push perceived limits, not a measured statistic."},
 {q:"How do psychologists describe resilience?", o:["Never feeling stress","Avoiding difficulty","Adapting well to adversity"], a:2, w:"Resilience is adapting to adversity and it can be built."},
 {q:"What helps discipline when motivation is low?", o:["Pre-made schedules and defaults","Waiting for inspiration","Punishing yourself"], a:0, w:"Decisions made in advance remove dependence on mood."}
]},
{ id:"mi05", cat:"mind", e:"🕯️", title:"Man's Search for Meaning", sub:"Viktor Frankl on purpose under pressure", cards:[
 {e:"📖", h:"The book's origin", t:"Viktor Frankl, an Austrian psychiatrist, survived several Nazi concentration camps, including Auschwitz. His book combines memoir with his theory of logotherapy, built on the idea that the main human drive is a search for meaning.", stat:{n:"9 days", l:"Frankl said he dictated the original text in about nine days in 1945"}},
 {e:"🧭", h:"The last freedom", t:"Frankl observed that prisoners lost nearly everything, yet some still chose their attitude. He wrote that between a stimulus and our response there is a space to choose. That choice is the freedom no one could remove."},
 {e:"🎯", h:"Meaning over pleasure", t:"Logotherapy contrasts with Freud's pleasure drive and Adler's power drive. Frankl argued people can endure almost any 'how' if they have a 'why.' Purpose gives suffering a direction instead of leaving it pointless."},
 {e:"🗝️", h:"Three sources of meaning", t:"Frankl said meaning can be found in several ways, and you can pursue any of them today. None requires perfect circumstances.", list:["Creating work or doing a deed","Experiencing love or beauty","Choosing your stance to suffering"]},
 {e:"⛓️", h:"Meaning in unavoidable pain", t:"Frankl did not praise suffering or say it is required. He said that when pain cannot be avoided, the way we carry it can still hold meaning. Avoidable suffering should be removed, not endured for its own sake."},
 {e:"🙋", h:"Ask what life asks", t:"Frankl suggested flipping the question. Instead of asking what you want from life, ask what life is asking of you. Meaning is found in responsibility toward a task, a person, or a cause outside yourself."},
 {e:"🌅", h:"The tragic optimism idea", t:"Frankl described staying hopeful despite pain, guilt and death by turning them into achievement, growth and responsible action. It is not denial. It is honest acknowledgment paired with a decision to act on what remains in your control."},
 {e:"🧪", h:"Read it with care", t:"Frankl's accounts are personal observation, and later historians question some generalizations about who survived. Use the book as philosophy and inspiration for purpose, not as a scientific guarantee about outcomes."}
], quiz:[
 {q:"What is the core idea of logotherapy?", o:["Pursuit of pleasure","Search for meaning is the main drive","Gaining power over others"], a:1, w:"Logotherapy holds that the will to meaning is the primary human motivation."},
 {q:"What 'last freedom' does Frankl describe?", o:["Leaving any situation","Controlling others","Choosing your attitude in any circumstances"], a:2, w:"He argued we can always choose our attitude to a given set of circumstances."},
 {q:"How should avoidable suffering be treated?", o:["Removed where possible","Embraced as noble","Ignored"], a:0, w:"Frankl said meaning applies to unavoidable suffering, not suffering that can be fixed."},
 {q:"Frankl suggests asking which question?", o:["What do I deserve?","What is life asking of me?","How do I avoid problems?"], a:1, w:"He reversed the question: life questions us, and we answer through responsibility."}
]},
{ id:"mi06", cat:"mind", e:"🏛️", title:"Stoicism and Meditations", sub:"Marcus Aurelius and practical philosophy", cards:[
 {e:"👑", h:"An emperor's notebook", t:"Marcus Aurelius ruled Rome from 161 to 180 AD and wrote private reminders to himself in Greek. The collection, now called Meditations, was never meant for publication. It reads like a daily practice for staying steady under pressure.", stat:{n:"161-180 AD", l:"reign of Marcus Aurelius"}},
 {e:"🎛️", h:"The dichotomy of control", t:"Epictetus, a major Stoic teacher, split the world into what is up to us (our judgments, choices, effort) and what is not (others' opinions, outcomes, the past). Put energy only into the first group and you lose less of it.", list:["Up to us: choices, effort, judgments","Not up to us: reputation, weather, results"]},
 {e:"🔍", h:"It's the judgment", t:"Stoics claim that events do not upset us directly; our interpretations do. When angry, ask what story you are adding. The goal is not feeling nothing but separating the facts from the extra judgment."},
 {e:"🌅", h:"Morning rehearsal", t:"Marcus began days by expecting difficult, ungrateful people. This is not pessimism but preparation. By imagining likely friction in advance, you lower the shock and have your response ready before the moment arrives."},
 {e:"⚰️", h:"Memento mori", t:"Stoics regularly reminded themselves that life is finite. The point is not gloom but clarity: time is limited, so spend it on what matters. Death as a reminder tends to cut through procrastination and petty grievance."},
 {e:"🚧", h:"The obstacle is the way", t:"Marcus wrote that what blocks the path becomes the path. A setback is raw material for practicing patience, creativity or courage. Ask what virtue this problem lets you exercise, then use it."},
 {e:"📝", h:"Evening review", t:"Seneca recommended nightly self-audit: what did I do well, where did I fall short, what will I change? Done without harsh judgment, this works like a short journal entry that tunes behavior day by day."},
 {e:"🧊", h:"Not emotionless", t:"A common myth says Stoics suppress feelings. Their aim is to feel less destructive passion and keep rational, caring responses. Modern cognitive behavioral therapy openly borrows the Stoic idea that thoughts shape emotions."}
], quiz:[
 {q:"Who wrote Meditations?", o:["Seneca","Plato","Marcus Aurelius"], a:2, w:"Marcus Aurelius wrote it as private notes to himself."},
 {q:"What is the dichotomy of control?", o:["Separating what is and is not up to you","Controlling other people","Avoiding all effort"], a:0, w:"It teaches you to focus on your own choices and judgments, not outcomes."},
 {q:"What does 'the obstacle is the way' suggest?", o:["Avoid obstacles","Setbacks can become material for growth","Obstacles are punishments"], a:1, w:"Marcus saw obstacles as occasions to practice virtue and ingenuity."},
 {q:"Which is true of Stoics and emotion?", o:["They aimed to feel nothing","They ignored reason","They aimed to reduce destructive passions"], a:2, w:"Stoicism seeks rational responses, not emotional numbness."}
]},
{ id:"mi07", cat:"mind", e:"♟️", title:"Power Books: A Critical Take", sub:"What 48 Laws-style books get right and wrong", cards:[
 {e:"📕", h:"What the book is", t:"Robert Greene's The 48 Laws of Power (1998) collects historical anecdotes into rules about gaining influence. It is written as a cold, strategic manual, and it is best read as a catalog of tactics rather than a moral guide."},
 {e:"👀", h:"Useful: awareness", t:"Even skeptics admit the book is good at exposing manipulation. Knowing the patterns, like flattery as a lever or credit-stealing, helps you recognize them when others use them on you at work or in negotiations."},
 {e:"📜", h:"Weak evidence base", t:"The laws rest on hand-picked stories chosen to fit each rule. There is no testing against failures, so survivorship bias is baked in. Anecdotes can illustrate a point but cannot show a tactic works reliably."},
 {e:"🤝", h:"Research says otherwise", t:"Adam Grant's studies of organizations found that generous 'givers' who also protect themselves often end up at the top. Reputation for trust compounds over many interactions, while cunning tactics tend to collapse once discovered."},
 {e:"🎭", h:"Hidden costs of deception", t:"Constantly guarding appearances and hiding motives is tiring and isolating. Relationships built on strategy are shallow and fragile. Many 'laws' trade long-term trust for short-term advantage, which is poor math in a small world."},
 {e:"🌿", h:"Take the healthy lessons", t:"Some advice survives scrutiny when stripped of manipulation: do not over-share your plans, let your work speak, pick your battles, and understand the incentives of others. These are prudence, not cruelty.", list:["Know others' incentives","Be selective about battles","Protect your reputation","Share plans cautiously"]},
 {e:"⚖️", h:"Ethics matter", t:"Using tactics designed to deceive can harm people and expose you to legal or social consequences. Ask whether you would be comfortable if the other person knew exactly what you were doing. If not, reconsider."},
 {e:"🧐", h:"How to read any guru book", t:"Check whether claims cite data or only stories, whether opposing cases are discussed, and whether the author gains from your belief. Treat bold rules as hypotheses to test in small, low-stakes situations."}
], quiz:[
 {q:"What kind of evidence supports the 48 Laws?", o:["Hand-picked historical anecdotes","Controlled experiments","Peer-reviewed meta-analysis"], a:0, w:"The book relies on selected stories, which risks survivorship bias."},
 {q:"What does Adam Grant's research suggest?", o:["Takers always win","Generous people who protect themselves can thrive","Trust is irrelevant"], a:1, w:"His work found savvy givers often reach top outcomes through reputation."},
 {q:"A good question to test a manipulative tactic is:", o:["Is it clever?","Will it be fast?","Would I be comfortable if they knew?"], a:2, w:"Transparency check reveals whether a tactic depends on deception."},
 {q:"What is the best use of such a book?", o:["Recognizing tactics and keeping prudent lessons","Following every law","Ignoring all strategy"], a:0, w:"Awareness and selective use keep the value while avoiding the harm."}
]},
{ id:"mi08", cat:"mind", e:"🎓", title:"Learning How to Learn", sub:"Evidence-based study strategies", cards:[
 {e:"🧩", h:"Retrieval beats rereading", t:"Testing yourself strengthens memory more than reading again. Close the book and write down everything you recall, then check. The effort of pulling information out is what builds durable knowledge, even though it feels harder."},
 {e:"📅", h:"Space it out", t:"Distributing study over days beats cramming. Each revisit comes right as you begin to forget, which strengthens the trace. Plan short sessions across a week, not one long session the night before."},
 {e:"🔀", h:"Interleave problems", t:"Mixing different problem types in one session feels messier than blocking by type, but it trains you to choose the right method. Studies in math and sports show better long-term performance despite worse practice scores."},
 {e:"🧒", h:"Teach it simply", t:"The Feynman technique means explaining a concept as if to a twelve-year-old. Gaps show up quickly when you cannot simplify. Return to the source for those gaps, then try again in plain words.", list:["Pick a concept","Explain it simply","Find the gaps","Review and simplify"]},
 {e:"⚡", h:"Desirable difficulty", t:"Psychologist Robert Bjork shows that conditions making learning feel slower, such as spacing and testing, often improve retention. Feeling fluent is not the same as learning. Aim for productive struggle, not smooth familiarity."},
 {e:"🎨", h:"Learning styles myth", t:"Reviews of research find little evidence that matching teaching to a preferred 'style' like visual or auditory improves outcomes. Better to match the method to the content: diagrams for geometry, listening for pronunciation."},
 {e:"🛌", h:"Sleep consolidates", t:"Sleep helps stabilize new memories, and skipping it harms attention and recall the next day. If you must choose between a last hour of cramming and a full night, the night usually wins for retention."},
 {e:"🌀", h:"Focused and diffuse", t:"Barbara Oakley describes focused mode for working a problem and diffuse mode for letting your mind wander during walks or breaks. Alternate them. Stuck problems often loosen after you step away for a while."}
], quiz:[
 {q:"Which technique usually beats rereading?", o:["Highlighting more","Practice testing yourself","Reading faster"], a:1, w:"Retrieval practice strengthens memory more than passive review."},
 {q:"What is spaced practice?", o:["Cramming in one session","Studying in a quiet space","Spreading study across several days"], a:2, w:"Spacing reviews over time improves long-term retention."},
 {q:"What does the evidence say about learning styles?", o:["Little support for matching instruction to style","Strong proof","They determine IQ"], a:0, w:"Reviews find weak evidence that style matching improves learning."},
 {q:"What is interleaving?", o:["Studying one topic at a time","Mixing problem types during practice","Sleeping between topics"], a:1, w:"Switching between types forces you to choose strategies, improving transfer."}
]},
{ id:"mi09", cat:"mind", e:"🏰", title:"Memory Techniques", sub:"Palaces, chunks and spaced review", cards:[
 {e:"📉", h:"The forgetting curve", t:"In the 1880s Hermann Ebbinghaus measured how quickly memorized nonsense syllables faded. Forgetting is steepest soon after learning, then slows. Reviewing at growing intervals flattens the curve and keeps knowledge alive.", stat:{n:"1885", l:"year Ebbinghaus published his forgetting curve work"}},
 {e:"🏠", h:"The memory palace", t:"The method of loci links items to places along a familiar route, like rooms in your home. Walking through mentally retrieves them in order. The technique dates to ancient Greece and is used by modern memory champions."},
 {e:"🎭", h:"Make images vivid", t:"Weird, vivid, emotional images stick better than abstract ones. To remember 'Smith', picture a blacksmith hammering your friend. Add movement, sound and exaggeration so each image is distinctive and hard to confuse.", list:["Make it vivid","Add action","Exaggerate size","Use your senses"]},
 {e:"📦", h:"Chunk to fit your mind", t:"Working memory handles only a few items at once; Cowan's estimate is about four chunks. Group digits or facts into meaningful units. 1-4-9-2 becomes the year Columbus sailed, one chunk instead of four.", stat:{n:"~4 chunks", l:"working memory capacity per Cowan; Miller's classic 7 plus or minus 2 was an overestimate"}},
 {e:"🔠", h:"Mnemonics and acronyms", t:"Acronyms and phrases compress lists into something memorable, like ROY G BIV for rainbow colors. Build your own for material you study, since personally made hooks work better than borrowed ones."},
 {e:"🔢", h:"Peg systems for numbers", t:"The major system converts digits into consonant sounds, which you fill with vowels to make words. Pegs let you turn 'numbers' into pictures. It takes practice but makes PINs, dates and long lists far easier."},
 {e:"🃏", h:"Spaced repetition apps", t:"Flashcard software schedules each card shortly before you would forget it. Write questions that test one idea, include your own cues, and review daily. Ten focused minutes beats occasional marathon sessions."},
 {e:"🧷", h:"Attach new to known", t:"Memory is associative. Connect new facts to what you already know, using stories, comparisons or personal experience. The more links a fact has, the more routes your mind has to retrieve it later."}
], quiz:[
 {q:"What did Ebbinghaus's curve show?", o:["Memory never fades","Learning is linear","Forgetting is fastest early on"], a:2, w:"Retention drops sharply soon after learning, then declines more slowly."},
 {q:"What is the method of loci?", o:["Linking items to places along a route","Repeating items aloud","Writing lists daily"], a:0, w:"It is the memory palace technique of placing images in familiar locations."},
 {q:"Roughly how many chunks can working memory hold?", o:["20","About 4","1"], a:1, w:"Modern estimates by Cowan suggest about four chunks."},
 {q:"Why use spaced repetition software?", o:["It makes cards look nicer","It removes the need to study","It reviews cards just before forgetting"], a:2, w:"Timed review boosts retention for less total time."}
]},
{ id:"mi10", cat:"mind", e:"📓", title:"Journaling That Works", sub:"Writing for clarity, not just diary entries", cards:[
 {e:"✍️", h:"Why write at all", t:"Putting thoughts on paper forces vague worry into specific words. Many people find that clarifying a problem in writing makes it feel more manageable and reveals decisions they were circling without noticing."},
 {e:"🧪", h:"Expressive writing studies", t:"James Pennebaker found that writing about stressful experiences for 15 to 20 minutes over several days was linked to benefits such as fewer doctor visits and improved mood in some studies. Effects are modest and vary, but the method is simple and free.", stat:{n:"15-20 min", l:"typical session in Pennebaker's expressive writing studies, over 3-4 days"}},
 {e:"🌅", h:"Morning pages", t:"Julia Cameron's morning pages are three handwritten pages of stream-of-consciousness each morning. The aim is to dump mental clutter before the day starts. It is not for sharing, so there is nothing to polish and no way to fail."},
 {e:"🙏", h:"Gratitude, kept honest", t:"Writing three specific good things each day can lift mood, but studies suggest specificity matters. 'My neighbor shoveled my steps' beats 'family.' Doing it a few times a week may work better than daily autopilot."},
 {e:"🔎", h:"Evening review prompts", t:"A short nightly review turns experience into learning. Keep it to five minutes so it survives busy weeks. Answer the same prompts every day to spot patterns across weeks.", list:["What went well?","What drained me?","What did I learn?","What is one priority tomorrow?"]},
 {e:"🔄", h:"Reframe on paper", t:"Cognitive behavioral approaches use thought records: write the situation, the automatic thought, the evidence for and against it, and a balanced alternative. Seeing the thought outside your head loosens its grip."},
 {e:"🗂️", h:"Decision journal", t:"Before important choices, record what you expect, why, and your confidence. Later compare with the outcome. This guards against hindsight bias and shows whether your judgment is well calibrated."},
 {e:"🪶", h:"Keep the bar low", t:"Perfectionism kills journaling. Two sentences count. Keep the notebook visible, pick a fixed time, and permit messy handwriting and half-finished thoughts. If rumination spirals, stop and talk with someone qualified."}
], quiz:[
 {q:"How long were Pennebaker's typical writing sessions?", o:["15 to 20 minutes","2 minutes","2 hours"], a:0, w:"Participants usually wrote 15 to 20 minutes for several consecutive days."},
 {q:"What are morning pages?", o:["A planner template","Three pages of unfiltered writing each morning","Daily news summaries"], a:1, w:"Julia Cameron's practice clears mental clutter with free writing."},
 {q:"Why keep a decision journal?", o:["To impress others","To avoid deciding","To compare predictions with outcomes"], a:2, w:"Comparing expectations to results fights hindsight bias and tests calibration."},
 {q:"What makes gratitude writing work better?", o:["Being specific","Writing the same items","Making it very long"], a:0, w:"Specific details feel more real and prompt deeper appreciation."}
]},
{ id:"mi11", cat:"mind", e:"🎯", title:"Goal Setting That Sticks", sub:"From wishes to weekly actions", cards:[
 {e:"📊", h:"Specific and hard", t:"Locke and Latham's research across decades finds that specific, challenging goals lead to higher performance than vague 'do your best' goals, as long as you have the ability and commitment to pursue them.", stat:{n:"~35 years", l:"span of Locke and Latham's goal-setting theory research summary (1990-2002)"}},
 {e:"🧭", h:"Process versus outcome", t:"You control actions more than results. Pair an outcome target, like 'publish a book', with process goals such as 'write 300 words each weekday'. Process goals give daily feedback and survive bad luck."},
 {e:"🔮", h:"Mental contrasting", t:"Gabriele Oettingen's WOOP method combines positive visualization with honest obstacles. Fantasizing alone can reduce effort. Naming the likely barrier and planning for it increases follow-through.", list:["Wish: what you want","Outcome: best result","Obstacle: inner barrier","Plan: if X, then Y"]},
 {e:"🧱", h:"If-then plans", t:"Peter Gollwitzer's implementation intentions turn goals into triggers: 'If it is 7 am, then I put on my running shoes.' A meta-analysis found they have a medium-to-large effect on goal attainment.", stat:{n:"d = .65", l:"effect size of implementation intentions in Gollwitzer and Sheeran's 2006 meta-analysis"}},
 {e:"✂️", h:"Break goals down", t:"A year-long goal is hard to feel. Split it into quarters, then months, then weekly targets. Each week, choose the next three actions. Clear next steps reduce procrastination caused by uncertainty."},
 {e:"🧍", h:"Limit active goals", t:"Trying to improve everything at once splits attention and willpower. Pick one to three priorities per season. Park the rest on a someday list so they are remembered but do not compete for today's energy."},
 {e:"🗓️", h:"Weekly review habit", t:"Once a week, ask what moved forward, what stalled, and what to change. Adjusting plans is not failure. It is how a goal survives contact with reality, especially when circumstances shift."},
 {e:"🎉", h:"Reward the progress", t:"Tracking visible progress, like a chart or checklist, helps motivation. Celebrate milestones, not just finish lines. A small celebration after each step connects effort to something pleasant and makes continuing easier."}
], quiz:[
 {q:"What kind of goals improve performance most?", o:["Vague best effort","Specific and challenging","Easy and flexible"], a:1, w:"Locke and Latham found specific, difficult goals yield the best results."},
 {q:"What does the O in WOOP stand for (second one)?", o:["Order","Option","Obstacle"], a:2, w:"WOOP = Wish, Outcome, Obstacle, Plan."},
 {q:"What is an if-then plan?", o:["A trigger linking a situation to an action","A backup budget","A reward system"], a:0, w:"Implementation intentions bind a cue to a specific response."},
 {q:"Why pair outcome goals with process goals?", o:["Outcomes never matter","You control actions more than results","Process goals are easier to ignore"], a:1, w:"Process goals give daily control and feedback."}
]},
{ id:"mi12", cat:"mind", e:"🌊", title:"Emotional Regulation Basics", sub:"Handling strong feelings skillfully", cards:[
 {e:"🌡️", h:"Feelings are signals", t:"Emotions carry information about what matters to you and what might be wrong. Regulation does not mean erasing them. It means choosing how to respond so the feeling informs your action instead of hijacking it."},
 {e:"🏷️", h:"Name it to tame it", t:"Matthew Lieberman's brain imaging studies found that putting feelings into words, called affect labeling, reduces amygdala activity in response to emotional images. Try specific words: not 'bad' but 'disappointed' or 'anxious about judgment'."},
 {e:"⏸️", h:"Pause before reacting", t:"Strong emotion narrows thinking. Create a gap between trigger and response: take a slow breath, count to ten, or leave the room briefly. Even ninety seconds of delay often lowers the urge to say something you regret."},
 {e:"💨", h:"Slow your exhale", t:"Breathing with a longer exhale than inhale, such as in for four, out for six, tends to calm the body's arousal. It is a quick, free tool for anxiety spikes, though it is a support, not a treatment for disorders.", list:["Inhale through nose, 4 counts","Exhale slowly, 6 counts","Repeat for a minute","Notice your shoulders drop"]},
 {e:"🔭", h:"Reappraise the story", t:"James Gross's research compares strategies. Cognitive reappraisal, reinterpreting a situation, usually works better than suppression, which hides outward expression but leaves inner distress. Ask what other explanation could be true.", stat:{n:"2 strategies", l:"Gross's model contrasts reappraisal (usually healthier) with suppression"}},
 {e:"🚶", h:"Move your body", t:"Physical activity, even a ten-minute walk, can help dissipate stress and shift mood. Movement gives your mind a break from rumination. Pair it with sunlight and conversation when you can for added benefit."},
 {e:"🛏️", h:"Fix the foundations", t:"Hunger, poor sleep and overload make emotions harder to manage. Before wrestling with a big feeling, check the basics: have you eaten, slept, hydrated, and taken breaks? Often the fix is partly physical."},
 {e:"🤲", h:"Know when to seek help", t:"Self-help tools work for everyday stress. If emotions feel overwhelming, persist for weeks, or affect safety or functioning, talk to a doctor or licensed therapist. Asking for support is a sign of good self-management."}
], quiz:[
 {q:"What is affect labeling?", o:["Hiding emotions","Ignoring triggers","Putting feelings into specific words"], a:2, w:"Naming emotions has been linked to reduced amygdala reactivity."},
 {q:"Which strategy tends to be healthier per Gross?", o:["Cognitive reappraisal","Suppression","Avoidance"], a:0, w:"Reappraisal changes the meaning of events, while suppression leaves distress."},
 {q:"A breathing pattern that helps calm the body uses:", o:["Rapid shallow breaths","Longer exhale than inhale","Holding breath for minutes"], a:1, w:"A longer exhale tends to lower arousal."},
 {q:"When should you seek professional help?", o:["Never","Only after a crisis","When distress persists or affects functioning"], a:2, w:"Persistent or overwhelming emotions merit a doctor or therapist."}
]},
{ id:"mi13", cat:"mind", e:"🎤", title:"Confidence and Public Speaking", sub:"Building calm, clear presence", cards:[
 {e:"🧗", h:"Confidence follows action", t:"Confidence usually grows from doing hard things and surviving them, not from feeling ready first. Albert Bandura called this mastery experience. Start with small stakes, collect evidence you can cope, and gradually raise the difficulty.", stat:{n:"4 sources", l:"Bandura's self-efficacy theory: mastery, modeling, persuasion, physiology"}},
 {e:"😬", h:"Nerves are normal", t:"Fear of public speaking is among the most common fears. Nerves and excitement feel similar physically. Research by Alison Wood Brooks suggests saying 'I am excited' can help performance more than trying to calm down."},
 {e:"🧱", h:"Structure your talk", t:"A clear structure makes you easier to follow and easier to remember. Start with one main message, support it with two or three points, and end with a call to action. Audiences remember little, so choose carefully.", list:["Hook in the first 30 seconds","One central message","Two or three points","Close with a clear ask"]},
 {e:"📖", h:"Use stories and examples", t:"Concrete stories and specific examples carry more weight than abstractions. Open with a short scene, a surprising fact, or a question. Then tie each point back to something the audience can picture or relate to."},
 {e:"🗣️", h:"Pace and pause", t:"Nervous speakers rush. Slow down, and use silence between ideas. A pause feels long to you but gives the audience time to absorb. Deliberate pauses also replace filler words like 'um' and 'you know'."},
 {e:"👁️", h:"Connect with people", t:"Look at one person at a time for a full thought, then move to another. Eye contact turns a speech into a series of conversations. Stand with feet planted and use natural gestures rather than hiding behind notes."},
 {e:"🎬", h:"Rehearse out loud", t:"Reading slides silently is not practice. Say the talk aloud, ideally standing and timed, at least three times. Record yourself on a phone to catch rushed sections. Practicing in front of a friend adds useful feedback."},
 {e:"🔁", h:"Reps build skill", t:"Speaking is a skill like any other. Join a group such as Toastmasters, volunteer to give updates at work, or present to a friend. Treat each talk as an experiment and note one thing to improve next time."}
], quiz:[
 {q:"What typically builds confidence most?", o:["Mastery experiences from doing","Affirmations alone","Avoiding challenge"], a:0, w:"Bandura found successful past attempts are the strongest source of self-efficacy."},
 {q:"What helped performance in Alison Wood Brooks' research?", o:["Telling yourself to calm down","Saying 'I am excited'","Avoiding the topic"], a:1, w:"Reappraising anxiety as excitement improved performance."},
 {q:"What should a talk center on?", o:["Many unrelated points","Reading every slide","One central message"], a:2, w:"A single clear message is easier to deliver and remember."},
 {q:"What do deliberate pauses do?", o:["Give listeners time to absorb","Lose attention","Cause nerves"], a:0, w:"Pauses emphasize ideas and replace filler words."}
]},
{ id:"mi14", cat:"mind", e:"📚", title:"Reading More, Better", sub:"Build the habit and keep what you read", cards:[
 {e:"⏰", h:"Start with minutes", t:"Reading twenty minutes a day adds up to a surprising number of pages. At an average pace of about 240 words per minute, that is roughly 1.7 million words a year, around twenty typical books.", stat:{n:"~20 books", l:"approximate yearly total at 20 minutes a day at an average reading speed"}},
 {e:"📱", h:"Swap the scroll", t:"Replace a moment of phone time with a book at the same cue. Keep a book where the phone usually sits: bedside table, couch, bag. The easier it is to pick up, the more often you will."},
 {e:"🎯", h:"Pick for pleasure first", t:"Reading habits die when every book feels like homework. Choose subjects you are curious about, and give yourself permission to quit a book after fifty pages. Your time is worth more than the sunk cost."},
 {e:"🧐", h:"Read actively", t:"Before reading a nonfiction book, skim the contents and ask what you want from it. While reading, underline sparingly and jot questions. Afterward, write a short summary in your own words from memory.", list:["Preview the structure","Ask a question","Mark key ideas","Summarize from memory"]},
 {e:"🗒️", h:"Take useful notes", t:"Passive highlighting gives an illusion of learning. Instead, write one-sentence takeaways and one idea you will apply. Rewriting ideas in your own words forces understanding and builds a personal knowledge bank."},
 {e:"🚫", h:"Speed reading myths", t:"Research reviews find that claims of reading thousands of words per minute with full comprehension do not hold up. Faster reading usually trades away understanding. Better strategy: read more often and match speed to difficulty."},
 {e:"🎧", h:"Audiobooks count", t:"Studies comparing listening and reading for narrative material find similar comprehension. Use audiobooks during commutes or chores to add reading time. Choose print or screen for dense material where you need to pause and review."},
 {e:"🔗", h:"Read with others", t:"A book club, a friend swapping recommendations, or a shared reading list adds accountability and discussion. Talking through ideas improves recall, and a deadline for the meeting turns good intentions into pages."}
], quiz:[
 {q:"Roughly how many books can 20 minutes daily yield per year?", o:["About 5","About 20","About 100"], a:1, w:"At ~240 wpm, this totals about 1.7 million words, near twenty books."},
 {q:"What is a good rule on books you dislike?", o:["Finish every one","Never start new ones","Give yourself permission to quit"], a:2, w:"Quitting bad fits frees time for better books."},
 {q:"What do reviews say about extreme speed reading?", o:["Comprehension tends to suffer","Comprehension holds fully","It is easy to learn"], a:0, w:"Claims of very high speeds with full comprehension are not supported."},
 {q:"What makes notes more effective than highlighting?", o:["Underlining everything","Restating ideas in your own words","Copying passages"], a:1, w:"Paraphrasing requires understanding and strengthens recall."}
]},
{ id:"mi15", cat:"mind", e:"⏳", title:"Time Management Systems", sub:"Spend attention on what matters", cards:[
 {e:"🟦", h:"The Eisenhower matrix", t:"Sort tasks by urgent and important. Do important and urgent now, schedule important but not urgent, delegate urgent but unimportant, and delete the rest. Most growth work sits in the 'important, not urgent' box and needs protected time.", list:["Urgent + important: do","Important only: schedule","Urgent only: delegate","Neither: delete"]},
 {e:"🍅", h:"Pomodoro technique", t:"Francesco Cirillo's method uses 25-minute focused sprints followed by 5-minute breaks, with a longer break after four rounds. The timer creates a small, bounded commitment that makes starting dreaded tasks easier.", stat:{n:"25 min", l:"standard Pomodoro work interval"}},
 {e:"🧱", h:"Time blocking", t:"Assign tasks to specific blocks on your calendar instead of working from a loose to-do list. This forces you to see how many hours you really have. Leave buffers, because most tasks take longer than planned."},
 {e:"🐸", h:"Eat the frog first", t:"Do your hardest or most dreaded task early, when energy and willpower are highest, before small distractions pile up. Finishing it first removes the background dread that colors the rest of the day."},
 {e:"📏", h:"Parkinson's law", t:"Work expands to fill the time available. Setting shorter deadlines, even self-imposed ones, tends to sharpen focus. Try giving a task half the time you think it needs, then adjust based on what actually happens."},
 {e:"⚖️", h:"The 80/20 lens", t:"The Pareto principle observes that a minority of inputs often drive most outcomes. It is not an exact law, but asking which 20 percent of activities yield most results helps you prune low-value commitments."},
 {e:"🙅", h:"Say no deliberately", t:"Every yes costs time elsewhere. Before agreeing, ask what you would drop to make room. A polite no with a short reason protects your priorities and leaves you able to deliver on what you do accept."},
 {e:"🔧", h:"Review and reset", t:"A weekly review keeps any system from decaying. Clear your inbox, check the calendar for the coming week, and choose your top three outcomes. David Allen's Getting Things Done calls this the key habit that keeps the system trusted."}
], quiz:[
 {q:"Which Eisenhower quadrant should you schedule?", o:["Urgent and important","Neither","Important but not urgent"], a:2, w:"Important, non-urgent work needs protected scheduled time."},
 {q:"How long is a standard Pomodoro?", o:["25 minutes","50 minutes","90 minutes"], a:0, w:"The classic interval is 25 minutes, followed by a 5-minute break."},
 {q:"What does Parkinson's law state?", o:["Tasks finish early","Work expands to fill available time","Deadlines never matter"], a:1, w:"Given more time, tasks tend to take more time."},
 {q:"Why do a weekly review?", o:["To add more tasks","To avoid planning","To keep your system current and trusted"], a:2, w:"Regular review prevents your system from decaying."}
]},
{ id:"mi16", cat:"mind", e:"🧰", title:"Decisions and Mental Models", sub:"Thinking tools for better choices", cards:[
 {e:"🗺️", h:"The map is not territory", t:"Alfred Korzybski's phrase reminds us that models simplify reality. A budget, a map or a theory is useful but incomplete. When reality disagrees with your model, update the model rather than blaming reality."},
 {e:"🔄", h:"Invert the problem", t:"Charlie Munger often advised thinking backward: instead of asking how to succeed, ask what would guarantee failure, then avoid it. Inversion reveals risks and blind spots that forward thinking misses."},
 {e:"🔮", h:"Run a pre-mortem", t:"Gary Klein's pre-mortem has a team imagine the project failed a year from now and list why. People speak more candidly when failure is assumed, surfacing risks early while there is still time to fix them.", stat:{n:"30%", l:"claimed increase in ability to identify reasons for outcomes using prospective hindsight (Mitchell et al., 1989)"}},
 {e:"🧮", h:"Second-order effects", t:"Ask 'and then what?' After the first consequence of a choice, trace the next one or two. A policy that helps in the short term may create new problems later. Thinking one step further prevents many avoidable mistakes."},
 {e:"🪓", h:"Occam's razor", t:"When several explanations fit the facts, prefer the simpler one as your starting hypothesis. It is not proof that simple is true, but it keeps you from inventing complicated stories without evidence."},
 {e:"🪤", h:"Common biases", t:"Many mistakes come from predictable biases, such as confirmation bias, sunk cost fallacy and overconfidence. Naming them does not remove them, but a checklist before big decisions reduces their influence.", list:["Confirmation: seeking agreeing evidence","Sunk cost: honoring past spend","Overconfidence: ranges too narrow","Anchoring: first number sticks"]},
 {e:"🚪", h:"Reversible or not", t:"Jeff Bezos describes one-way and two-way door decisions. Reversible choices should be made quickly by small teams, since mistakes are cheap. Spend deliberate time only on the few decisions that are hard to undo."},
 {e:"🏁", h:"Decide, then review", t:"Write down your reasoning and expected outcome before the result is known. Later, judge the decision process separately from the outcome, since good decisions sometimes fail by luck and bad ones sometimes succeed."}
], quiz:[
 {q:"What does inversion suggest?", o:["Ask what would guarantee failure, then avoid it","Copy others","Wait for certainty"], a:0, w:"Thinking backward uncovers hazards that forward planning misses."},
 {q:"What is a pre-mortem?", o:["Reviewing after completion","Imagining the project failed and listing why","Hiring an auditor"], a:1, w:"Assuming failure helps people surface risks candidly in advance."},
 {q:"Which decisions should be made quickly according to Bezos?", o:["Irreversible ones","None","Two-way door (reversible) ones"], a:2, w:"Reversible decisions have cheap mistakes, so speed is fine."},
 {q:"What does 'the map is not the territory' mean?", o:["Models simplify and can be wrong","Maps are always accurate","Territory changes daily"], a:0, w:"Models are useful simplifications, not reality itself."}
]}
);
window.TIPS.push(
{cat:"mind", e:"⏱️", h:"Two-minute start", t:"If a task feels heavy, commit to just two minutes. Starting is the hardest part, and momentum usually carries you further."},
{cat:"mind", e:"📵", h:"Phone out of sight", t:"Put your phone in another room during focused work. Even a visible phone on the desk can quietly drain attention."},
{cat:"mind", e:"🪪", h:"Vote for identity", t:"Each small action is a vote for who you are becoming. Ask what a person who is healthy would do right now."},
{cat:"mind", e:"🔗", h:"Stack it", t:"Attach a new habit to an existing one: after I pour coffee, I write one sentence. The old habit becomes the cue."},
{cat:"mind", e:"🌱", h:"Add 'yet'", t:"Swap 'I can't do this' for 'I can't do this yet.' One word reframes a limit as a stage."},
{cat:"mind", e:"🎛️", h:"Control what you can", t:"List what is up to you and what is not. Spend your energy only on the first list."},
{cat:"mind", e:"🧩", h:"Test, don't reread", t:"Close the book and write what you remember. Retrieval strengthens memory far more than passive rereading."},
{cat:"mind", e:"📅", h:"Space your study", t:"Three 20-minute sessions across a week beat one hour of cramming. Spacing builds lasting memory."},
{cat:"mind", e:"🧒", h:"Explain it simply", t:"If you cannot explain an idea to a twelve-year-old, you probably have not mastered it yet."},
{cat:"mind", e:"🏠", h:"Build a palace", t:"Place memorable images along a familiar route in your home. Walk it mentally to recall items in order."},
{cat:"mind", e:"📦", h:"Chunk it", t:"Group numbers or facts into meaningful units. Working memory holds only about four chunks at once."},
{cat:"mind", e:"🏷️", h:"Name the feeling", t:"Use a specific word for your emotion, like disappointed or anxious. Labeling feelings tends to lower their intensity."},
{cat:"mind", e:"💨", h:"Longer exhale", t:"Breathe in for four, out for six. A longer exhale helps settle the body quickly."},
{cat:"mind", e:"⏸️", h:"Wait ninety seconds", t:"Before replying in anger, wait. Urges often fade once the first surge of emotion passes."},
{cat:"mind", e:"📓", h:"Write for ten", t:"Ten minutes of honest writing about a stressor can clarify your thinking. Keep it private so you can be candid."},
{cat:"mind", e:"🌙", h:"Evening review", t:"Ask nightly: what went well, what drained me, what is my one priority tomorrow? Five minutes is enough."},
{cat:"mind", e:"🎯", h:"Make goals specific", t:"'Write 300 words at 7 am' beats 'write more.' Specific, challenging targets outperform vague ones."},
{cat:"mind", e:"🧱", h:"If-then plans", t:"Say 'If it is 7 am, then I put on running shoes.' Linking cue to action raises follow-through."},
{cat:"mind", e:"🔮", h:"Plan for obstacles", t:"Visualizing success is not enough. Name the likely obstacle and decide in advance how you will handle it."},
{cat:"mind", e:"🐸", h:"Hardest task first", t:"Do your most dreaded task early. The relief and momentum lift the rest of the day."},
{cat:"mind", e:"🍅", h:"Try a 25-minute sprint", t:"Set a timer for 25 focused minutes, then rest for five. A bounded sprint makes starting easier."},
{cat:"mind", e:"🟦", h:"Protect important work", t:"Schedule the important but not urgent tasks. If they only get leftovers, they never happen."},
{cat:"mind", e:"🙅", h:"A deliberate no", t:"Before saying yes, ask what you would drop to make room. Every yes costs time somewhere else."},
{cat:"mind", e:"🧊", h:"Practice discomfort", t:"Do one small hard thing daily, like a cold finish to the shower. Gentle exposure builds tolerance."},
{cat:"mind", e:"🧭", h:"Ask what life asks", t:"Frankl suggested asking not what you want from life, but what life is asking of you."},
{cat:"mind", e:"🌅", h:"Morning rehearsal", t:"Imagine today's likely friction before it arrives. Expecting difficulty reduces shock and prepares a calm response."},
{cat:"mind", e:"🚧", h:"Use the obstacle", t:"Ask what virtue a problem lets you practice: patience, creativity or courage. Then use it."},
{cat:"mind", e:"⚰️", h:"Remember limits", t:"Time is finite. Let that clarify what deserves your hours and what petty things you can drop."},
{cat:"mind", e:"🔄", h:"Invert the problem", t:"Ask what would guarantee failure, then avoid it. Thinking backward exposes blind spots."},
{cat:"mind", e:"🔮", h:"Run a pre-mortem", t:"Imagine the project failed and list why. People are more candid about risks when failure is assumed."},
{cat:"mind", e:"🧮", h:"And then what?", t:"Trace the second-order effects of a choice. One more step of thought prevents many regrets."},
{cat:"mind", e:"🚪", h:"One-way or two-way", t:"Decide reversible choices fast. Save slow deliberation for decisions that are hard to undo."},
{cat:"mind", e:"🪤", h:"Spot sunk costs", t:"Past spending should not decide your next move. Ask what you would choose if starting fresh today."},
{cat:"mind", e:"🗒️", h:"Decision journal", t:"Write your reasoning and confidence before the outcome. Later compare, and judge process separately from luck."},
{cat:"mind", e:"📖", h:"Read 20 minutes", t:"Twenty minutes a day adds up to roughly twenty books a year. Start small and keep the book visible."},
{cat:"mind", e:"🚪", h:"Quit bad books", t:"Give yourself permission to drop a book after fifty pages. Your time is worth more than the sunk cost."},
{cat:"mind", e:"🧐", h:"Summarize from memory", t:"After a chapter, write three sentences without looking. The struggle to recall is what makes it stick."},
{cat:"mind", e:"🎧", h:"Audiobooks count", t:"Listening gives similar comprehension for narrative material. Use commutes and chores to add reading time."},
{cat:"mind", e:"🎤", h:"Say it aloud", t:"Rehearse speeches out loud, standing and timed. Silent reading of slides is not real practice."},
{cat:"mind", e:"⏸️", h:"Pause instead of um", t:"A deliberate silence feels long to you but lands as confidence. It also replaces filler words."},
{cat:"mind", e:"🎬", h:"Record yourself", t:"Film a practice talk on your phone. You will spot rushed sections and habits you cannot hear in the moment."},
{cat:"mind", e:"😬", h:"Call nerves excitement", t:"Saying 'I am excited' before speaking can help more than trying to calm down. The body feels similar."},
{cat:"mind", e:"🧱", h:"One main message", t:"Build every talk around a single idea. Audiences remember little, so choose what matters most."},
{cat:"mind", e:"📈", h:"1% better", t:"Getting one percent better daily compounds to roughly 37 times better in a year. Direction beats size."},
{cat:"mind", e:"🕰️", h:"Never miss twice", t:"One missed day is an accident. Two starts a new habit. Make the next day your top priority."},
{cat:"mind", e:"🏠", h:"Shape your space", t:"Make good cues visible and bad cues invisible. Environment often beats willpower."},
{cat:"mind", e:"🌀", h:"Step away to think", t:"When stuck, take a walk. Letting your mind wander often loosens problems that focus alone could not."},
{cat:"mind", e:"🛌", h:"Protect sleep", t:"Sleep consolidates memory. A full night usually beats an extra hour of cramming."},
{cat:"mind", e:"⚖️", h:"Practice self-compassion", t:"Treat yourself like a friend after a mistake. Kindness supports recovery better than harsh self-criticism."},
{cat:"mind", e:"🧠", h:"Mistakes are data", t:"After a failure, ask what it reveals and which strategy to try next, not what it says about you."},
{cat:"mind", e:"🗓️", h:"Weekly review", t:"Spend ten minutes each week checking what moved, what stalled, and your top three priorities ahead."},
{cat:"mind", e:"📏", h:"Shorten the deadline", t:"Work expands to fill time. Give a task less time than you think it needs and see what happens."},
{cat:"mind", e:"🌿", h:"Rest is productive", t:"Real downtime restores focus. A shutdown ritual at day's end lets your mind fully disengage."},
{cat:"mind", e:"🎭", h:"Judge process, not luck", t:"Good decisions sometimes fail and bad ones sometimes work. Review your reasoning, not just the result."},
{cat:"mind", e:"📚", h:"Think in models", t:"Collect a handful of mental models and apply them often. Each gives you a different lens on the same problem."},
{cat:"mind", e:"🔭", h:"Test big claims", t:"Treat bold self-help rules as hypotheses. Try them in small, low-stakes situations before betting on them."},
{cat:"mind", e:"🤲", h:"Ask for help", t:"If stress or low mood persists for weeks or hurts daily life, talk to a doctor or licensed therapist."},
{cat:"mind", e:"🚶", h:"Walk it out", t:"A ten-minute walk can ease stress and break a rumination loop. Add daylight if you can."},
{cat:"mind", e:"✍️", h:"Be specific in thanks", t:"Write specific gratitude, like 'my neighbor shoveled my steps.' Detail makes appreciation feel real."},
{cat:"mind", e:"🙋", h:"Praise effort", t:"Praise strategy and effort, not talent, in yourself and others. It keeps people willing to try hard things."}
);
